test('mergeCustomers removes fromId customer', () => {
  const customers = [
    { id: 'C-001', name: 'Northwind Studio', email: 'accounts@northwind.example', country: 'NL', tier: 'gold' },
    { id: 'C-002', name: 'Blue Fern Bakery', email: 'hello@bluefern.example', country: 'NL', tier: 'standard' },
  ];
  const invoices = [];

  const r = mergeCustomers(customers, invoices, 'C-001', 'C-002');
  assert.equal(r.ok, true);
  assert.equal(r.value.customers.length, 1);
  assert.equal(r.value.customers[0].id, 'C-002');
});

test('mergeCustomers reassigns invoices from fromId to intoId', () => {
  const customers = [
    { id: 'C-001', name: 'Northwind Studio', email: 'accounts@northwind.example', country: 'NL', tier: 'gold' },
    { id: 'C-002', name: 'Blue Fern Bakery', email: 'hello@bluefern.example', country: 'NL', tier: 'standard' },
  ];
  const invoices = [
    { customerId: 'C-001', number: 'INV-2026-0001', issueDate: '2026-01-01', status: 'issued', lines: [] },
    { customerId: 'C-001', number: 'INV-2026-0002', issueDate: '2026-01-15', status: 'issued', lines: [] },
    { customerId: 'C-002', number: 'INV-2026-0003', issueDate: '2026-01-20', status: 'issued', lines: [] },
  ];

  const r = mergeCustomers(customers, invoices, 'C-001', 'C-002');
  assert.equal(r.ok, true);
  assert.equal(r.value.invoices.length, 3);
  assert.equal(r.value.invoices[0].customerId, 'C-002');
  assert.equal(r.value.invoices[1].customerId, 'C-002');
  assert.equal(r.value.invoices[2].customerId, 'C-002');
});

test('mergeCustomers reports CUSTOMER_NOT_FOUND if fromId does not exist', () => {
  const customers = [
    { id: 'C-001', name: 'Northwind Studio', email: 'accounts@northwind.example', country: 'NL', tier: 'gold' },
  ];
  const invoices = [];

  const r = mergeCustomers(customers, invoices, 'C-999', 'C-001');
  assert.deepEqual(r, { ok: false, error: 'CUSTOMER_NOT_FOUND' });
});

test('mergeCustomers reports CUSTOMER_NOT_FOUND if intoId does not exist', () => {
  const customers = [
    { id: 'C-001', name: 'Northwind Studio', email: 'accounts@northwind.example', country: 'NL', tier: 'gold' },
  ];
  const invoices = [];

  const r = mergeCustomers(customers, invoices, 'C-001', 'C-999');
  assert.deepEqual(r, { ok: false, error: 'CUSTOMER_NOT_FOUND' });
});

test('mergeCustomers reports SAME_CUSTOMER if fromId equals intoId', () => {
  const customers = [
    { id: 'C-001', name: 'Northwind Studio', email: 'accounts@northwind.example', country: 'NL', tier: 'gold' },
